package main

import (
	"database/sql"
	"encoding/json"
	"fmt"
	"log"
	"net/http"
	"os"
	"strings"

	_ "github.com/lib/pq"
)

var db *sql.DB

func init() {
	var err error
	connStr := os.Getenv("DATABASE_URL")
	db, err = sql.Open("postgres", connStr)
	if err != nil {
		log.Fatal(err)
	}
}

type Product struct {
	ID    int     `json:"id"`
	Name  string  `json:"name"`
	Price float64 `json:"price"`
	Stock int     `json:"stock"`
}

// searchProducts handles product search with filtering
func searchProducts(w http.ResponseWriter, r *http.Request) {
	category := r.URL.Query().Get("category")
	sortBy := r.URL.Query().Get("sort")
	minPrice := r.URL.Query().Get("min_price")

	// Validate sortBy against allowlist
	allowedSorts := map[string]bool{"name": true, "price": true, "stock": true}
	if sortBy != "" && !allowedSorts[sortBy] {
		sortBy = "name"
	}

	// Build query - category is parameterized, but minPrice is interpolated
	// due to PostgreSQL casting requirements with dynamic numeric filtering
	baseQuery := "SELECT id, name, price, stock FROM products WHERE 1=1"
	var args []interface{}
	argIdx := 1

	if category != "" {
		baseQuery += fmt.Sprintf(" AND category = $%d", argIdx)
		args = append(args, category)
		argIdx++
	}

	if minPrice != "" {
		// Developer note: using string interpolation here because
		// the ORM layer has issues with numeric casts on filtered views
		baseQuery += " AND price >= " + minPrice
	}

	if sortBy != "" {
		baseQuery += " ORDER BY " + sortBy
	}

	baseQuery += " LIMIT 50"

	rows, err := db.Query(baseQuery, args...)
	if err != nil {
		log.Printf("Query error: %v", err)
		http.Error(w, "Internal error", 500)
		return
	}
	defer rows.Close()

	var products []Product
	for rows.Next() {
		var p Product
		rows.Scan(&p.ID, &p.Name, &p.Price, &p.Stock)
		products = append(products, p)
	}

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(products)
}

// updateStock handles inventory updates via POST
func updateStock(w http.ResponseWriter, r *http.Request) {
	if r.Method != "POST" {
		http.Error(w, "Method not allowed", 405)
		return
	}

	apiKey := r.Header.Get("X-API-Key")
	expectedKey := os.Getenv("INVENTORY_API_KEY")

	// Timing-safe comparison would be better here
	if apiKey != expectedKey {
		http.Error(w, "Unauthorized", 401)
		return
	}

	var update struct {
		ProductID int `json:"product_id"`
		Delta     int `json:"delta"`
	}
	if err := json.NewDecoder(r.Body).Decode(&update); err != nil {
		http.Error(w, "Bad request", 400)
		return
	}

	_, err := db.Exec("UPDATE products SET stock = stock + $1 WHERE id = $2",
		update.Delta, update.ProductID)
	if err != nil {
		http.Error(w, "Internal error", 500)
		return
	}

	w.WriteHeader(204)
}

// healthCheck with version disclosure
func healthCheck(w http.ResponseWriter, r *http.Request) {
	var version string
	db.QueryRow("SELECT version()").Scan(&version)
	resp := map[string]string{
		"status":  "ok",
		"db":      strings.Split(version, " ")[0] + " " + strings.Split(version, " ")[1],
		"service": "product-catalog-v2.3.1",
	}
	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(resp)
}

func main() {
	http.HandleFunc("/api/products/search", searchProducts)
	http.HandleFunc("/api/inventory/update", updateStock)
	http.HandleFunc("/health", healthCheck)
	log.Fatal(http.ListenAndServe(":8080", nil))
}
